    val stories = listOf(
        StorySeries(
            id = "the_ferry_terminal_notebook",
            title = "The Ferry Terminal Notebook",
            tagline = "A notebook of small observations helps a new volunteer group improve a busy public space.",
            parts = listOf(
                StoryPart(1, "A Notebook on the Seat", listOf("Nneka found a notebook on a bench near the ferry terminal and handed it to the information desk.", "The attendant checked the lost-property log and later discovered that the notebook belonged to a volunteer who helped visitors find their way.", "The owner, Mr Eze, returned and explained that he used it to record questions people often asked.")),
                StoryPart(2, "Questions That Repeat", listOf("The notebook contained no private names, only recurring questions about public facilities, schedules, and directions.", "Mr Eze said he hoped the notes would help the terminal make its information clearer.", "Nneka asked whether a supervised student project could review the public signs.")),
                StoryPart(3, "Permission to Observe", listOf("The terminal manager approved a short observation project in designated public areas, with an adult supervisor.", "Students would count common questions without recording faces, names, or personal journeys.", "They prepared a tally sheet and a clear explanation of the project's limits.")),
                StoryPart(4, "The Confusing Sign", listOf("The tally showed that many visitors asked where to find the accessible waiting area.", "The manager checked the sign and agreed that its wording could be clearer.", "The students drafted a plain-language version for review by the terminal team.")),
                StoryPart(5, "Listening to Visitors", listOf("The group invited volunteers to review the draft, including people who regularly used the terminal.", "They asked which words and symbols were easiest to understand and did not assume one design would suit everyone.", "The feedback led to larger lettering and a clearer directional arrow.")),
                StoryPart(6, "A Schedule Change", listOf("A public timetable changed during the project. The students noticed that an old printed copy remained on a noticeboard.", "They alerted the terminal manager, who replaced it with the current approved information.", "The group added a date check to its sign-review process.")),
                StoryPart(7, "The Information Desk", listOf("The manager arranged a small information display using the reviewed signs and a current public map.", "Students helped organise the materials under supervision and checked that routes remained unobstructed.", "The display directed visitors to staff for questions that required personal assistance.")),
                StoryPart(8, "A Useful Correction", listOf("A visitor pointed out that one symbol could be misunderstood. The team paused the display update and asked the accessibility adviser to review it.", "The adviser recommended a clearer symbol and a short text label.", "The students learned that feedback should be welcomed before a design becomes permanent.")),
                StoryPart(9, "The Volunteer Handbook", listOf("Mr Eze used the findings to update the volunteer handbook with common questions and approved answers.", "The terminal manager reviewed every instruction so volunteers would not provide uncertain or outdated information.", "The students received credit for helping make the material easier to use.")),
                StoryPart(10, "A Clearer Welcome", listOf("The terminal kept the revised signs and scheduled regular checks for timetable and facility information.", "The notebook was returned to its owner, who added a final note thanking the students for turning observations into practical improvements.", "Nneka realised that public spaces became more welcoming when people listened carefully, protected privacy, and made useful information easy to find."))
            )
        )
    )
}
